     1|/**
     2| * CanonicalInvestmentReelCard — the ONE shared reel card for IVX.
     3| *
     4| * Used by:
     5| *   • Main/Home feed (mode="feed")
     6| *   • Reels module (mode="reel")
     7| *   • Landing page (mode="feed")
     8| *
     9| * Visual design (owner-approved):
    10| *   Full-bleed vertical media (video or image)
    11| *   Investment + Active badges (top-left)
    12| *   Property title + location (bottom-left, over gradient)
    13| *   ROI / Min Investment / Min Ownership metrics
    14| *   Tokenized / JV Deal / Buyer category options
    15| *   Right-side action rail: Like, Comment, Save, Share, Audio
    16| *   View Deal + Invest Now CTAs (bottom)
    17| *
    18| * Data sources:
    19| *   Accepts a unified `CanonicalReelData` props object that can be
    20| *   mapped from FeedVideo, HomeFeedDeal, PublishedDealCardModel, or
    21| *   ParsedJVDeal — all via the adapter functions in this file.
    22| */
    23|import React, { memo, useCallback, useEffect, useMemo, useRef, useState } from 'react';
    24|import {
    25|  View,
    26|  Text,
    27|  StyleSheet,
    28|  TouchableOpacity,
    29|  Share,
    30|  Alert,
    31|  AppState,
    32|  Platform,
    33|  useWindowDimensions,
    34|  type ViewStyle,
    35|} from 'react-native';
    36|import { ResizeMode } from 'expo-av';
    37|import { LinearGradient } from 'expo-linear-gradient';
    38|import { Image } from 'expo-image';
    39|import { useSafeAreaInsets } from 'react-native-safe-area-context';
    40|import * as Haptics from 'expo-haptics';
    41|import {
    42|  Heart,
    43|  MessageCircle,
    44|  Share2,
    45|  Bookmark,
    46|  Volume2,
    47|  VolumeX,
    48|  Play,
    49|  Hexagon,
    50|  Users,
    51|  Home,
    52|} from 'lucide-react-native';
    53|import Colors from '@/constants/colors';
    54|import SafeVideo from '@/components/SafeVideo';
    55|import ReelVideoPlayer from '@/components/ReelVideoPlayer';
    56|import { formatCount, compactCurrency } from '@/lib/reel-formatters';
    57|import { toggleProjectLike, trackProjectShare } from '@/lib/project-engagement';
    58|import { toggleVideoSave, getViewerId, buildVideoShareUrl } from '@/lib/video-platform';
    59|
    60|// ─── Types ─────────────────────────────────────────────────────────────
    61|
    62|export type ReelMode = 'reel' | 'feed';
    63|export type ReelMediaType = 'video' | 'image';
    64|
    65|export interface CanonicalReelData {
    66|  /** Unique identifier for this reel item (video ID or deal ID). */
    67|  reelId: string;
    68|  /** Linked JV deal ID (used for View Deal / Invest Now navigation). */
    69|  dealId: string | null;
    70|  /** Property ID if different from dealId. */
    71|  propertyId: string | null;
    72|  /** Investment ID if different from dealId. */
    73|  investmentId: string | null;
    74|  /** URL slug for deep linking. */
    75|  slug: string | null;
    76|  /** Display title (property name or video title). */
    77|  title: string;
    78|  /** Subtitle / tour label. */
    79|  subtitle: string;
    80|  /** Location string (city, state). */
    81|  location: string | null;
    82|  /** Primary media URL (video or image). */
    83|  mediaUrl: string | null;
    84|  /** Media type — video or image. */
    85|  mediaType: ReelMediaType;
    86|  /** HLS adaptive stream URL (preferred for video). */
    87|  hlsUrl: string | null;
    88|  /** Poster/thumbnail URL for video. */
    89|  posterUrl: string | null;
    90|  /** Blurred placeholder URL for instant first paint. */
    91|  previewBlurUrl: string | null;
    92|  /** Expected ROI percentage. */
    93|  roi: number | null;
    94|  /** Minimum investment amount in dollars. */
    95|  minimumInvestment: number | null;
    96|  /** Minimum ownership percentage. */
    97|  minimumOwnership: string | null;
    98|  /** Deal status (published, active, etc.). */
    99|  status: string;
   100|  /** Deal category (jv, development, etc.). */
   101|  category: string | null;
   102|  /** Like count. */
   103|  likeCount: number;
   104|  /** Comment count. */
   105|  commentCount: number;
   106|  /** Save count. */
   107|  saveCount: number;
   108|  /** Share count. */
   109|  shareCount: number;
   110|  /** Whether the current user has liked this reel. */
   111|  isLiked: boolean;
   112|  /** Whether the current user has saved this reel. */
   113|  isSaved: boolean;
   114|  /** Whether audio is enabled (video only). */
   115|  audioEnabled: boolean;
   116|  /** Creator ID for follow tracking. */
   117|  creatorId: string | null;
   118|  /** Full deal URL for deep-link navigation. */
   119|  dealUrl: string | null;
   120|}
   121|
   122|export interface CanonicalInvestmentReelCardProps {
   123|  data: CanonicalReelData;
   124|  mode: ReelMode;
   125|  /** Whether this card is the active/visible item (reel mode only). */
   126|  isActive: boolean;
   127|  /** Whether to mount the video player (reel mode — active ± 1 only). */
   128|  shouldMountVideo: boolean;
   129|  /** Whether audio is muted globally (reel mode). */
   130|  isMuted: boolean;
   131|  /** Card height for feed mode (default: 520). */
   132|  feedHeight: number;
   133|  /** Callbacks. */
   134|  onOpenDeal: (data: CanonicalReelData) => void;
   135|  onInvest: (data: CanonicalReelData) => void;
   136|  onLike: (data: CanonicalReelData) => void;
   137|  onComment: (data: CanonicalReelData) => void;
   138|  onSave: (data: CanonicalReelData) => void;
   139|  onShare: (data: CanonicalReelData) => void;
   140|  onToggleMute: () => void;
   141|  /** Test ID prefix. */
   142|  testIDPrefix?: string;
   143|}
   144|
   145|// ─── Investment options ────────────────────────────────────────────────
   146|
   147|interface InvestmentOption {
   148|  id: string;
   149|  label: string;
   150|  icon: React.ReactNode;
   151|  tint: string;
   152|}
   153|
   154|function useInvestmentOptions(dealType: string | null | undefined): InvestmentOption[] {
   155|  const t = (dealType ?? '').toLowerCase();
   156|  const tokenized: InvestmentOption = {
   157|    id: 'tokenized',
   158|    label: 'Tokenized',
   159|    icon: <Hexagon size={16} color={Colors.primary} />,
   160|    tint: Colors.primary,
   161|  };
   162|  const jvDeals: InvestmentOption = {
   163|    id: 'jvDeals',
   164|    label: 'JV Deal',
   165|    icon: <Users size={16} color={Colors.blue} />,
   166|    tint: Colors.blue,
   167|  };
   168|  const buyers: InvestmentOption = {
   169|    id: 'buyers',
   170|    label: 'Buyer',
   171|    icon: <Home size={16} color={Colors.green} />,
   172|    tint: Colors.green,
   173|  };
   174|  switch (t) {
   175|    case 'jv':
   176|    case 'equity_split':
   177|    case 'hybrid':
   178|      return [tokenized, jvDeals, buyers];
   179|    case 'development':
   180|    case 'new_construction':
   181|    case 'rehab_construction':
   182|      return [jvDeals, tokenized, buyers];
   183|    case 'profit_sharing':
   184|      return [tokenized, buyers, jvDeals];
   185|    default:
   186|      return [tokenized, jvDeals, buyers];
   187|  }
   188|}
   189|
   190|// ─── Component ─────────────────────────────────────────────────────────
   191|
   192|const CanonicalInvestmentReelCard = memo(function CanonicalInvestmentReelCard({
   193|  data,
   194|  mode,
   195|  isActive,
   196|  shouldMountVideo,
   197|  isMuted,
   198|  feedHeight = 520,
   199|  onOpenDeal,
   200|  onInvest,
   201|  onLike,
   202|  onComment,
   203|  onSave,
   204|  onShare,
   205|  onToggleMute,
   206|  testIDPrefix = 'reel-card',
   207|}: CanonicalInvestmentReelCardProps) {
   208|  const insets = useSafeAreaInsets();
   209|  const { height: screenHeight } = useWindowDimensions();
   210|  const [paused, setPaused] = useState<boolean>(false);
   211|  const [showHeart, setShowHeart] = useState<boolean>(false);
   212|  const [progress, setProgress] = useState<number>(0);
   213|  const [liked, setLiked] = useState<boolean>(data.isLiked);
   214|  const [likeCount, setLikeCount] = useState<number>(data.likeCount);
   215|  const [saved, setSaved] = useState<boolean>(data.isSaved);
   216|  const [saveCount, setSaveCount] = useState<number>(data.saveCount);
   217|  const [viewerId, setViewerId] = useState<string | null>(null);
   218|  const [appState, setAppState] = useState<string>('active');
   219|  const [isInViewport, setIsInViewport] = useState<boolean>(false);
   220|  const lastTapRef = useRef<number>(0);
   221|  const viewRef = useRef<View>(null);
   222|
   223|  const isReel = mode === 'reel';
   224|  const cardHeight = isReel ? screenHeight : feedHeight;
   225|
   226|  // Fetch viewer ID for engagement tracking
   227|  useEffect(() => {
   228|    let cancelled = false;
   229|    void getViewerId().then((id) => {
   230|      if (!cancelled) setViewerId(id);
   231|    });
   232|    return () => { cancelled = true; };
   233|  }, []);
   234|
   235|  // Pause video when app goes to background
   236|  useEffect(() => {
   237|    const subscription = AppState.addEventListener('change', (nextState: string) => {
   238|      setAppState(nextState);
   239|    });
   240|    return () => subscription.remove();
   241|  }, []);
   242|
   243|  // Viewability detection for feed mode
   244|  useEffect(() => {
   245|    if (isReel) return; // reel mode uses isActive from parent
   246|    const interval = setInterval(() => {
   247|      if (!viewRef.current || appState !== 'active') {
   248|        setIsInViewport(false);
   249|        return;
   250|      }
   251|      viewRef.current.measure((_x, _y, w, h, pageX, pageY) => {
   252|        if (!h || h <= 0) return;
   253|        const visibleTop = Math.max(pageY, 0);
   254|        const visibleBottom = Math.min(pageY + h, screenHeight);
   255|        const visibleHeight = Math.max(0, visibleBottom - visibleTop);
   256|        const visibilityRatio = visibleHeight / h;
   257|        setIsInViewport(visibilityRatio >= 0.6);
   258|      });
   259|    }, 500);
   260|    return () => clearInterval(interval);
   261|  }, [appState, screenHeight, isReel]);
   262|
   263|  const shouldPlay = isReel
   264|    ? isActive && !paused && appState === 'active'
   265|    : isInViewport && appState === 'active' && !paused;
   266|
   267|  const investmentOptions = useInvestmentOptions(data.category);
   268|  const isActiveStatus = (data.status ?? 'published') === 'published';
   269|  const hasDeal = data.dealId !== null;
   270|
   271|  // Sync local state when props change
   272|  useEffect(() => {
   273|    setLiked(data.isLiked);
   274|    setLikeCount(data.likeCount);
   275|  }, [data.isLiked, data.likeCount]);
   276|
   277|  useEffect(() => {
   278|    setSaved(data.isSaved);
   279|    setSaveCount(data.saveCount);
   280|  }, [data.isSaved, data.saveCount]);
   281|
   282|  const handleTap = useCallback(() => {
   283|    if (data.mediaType !== 'video') return;
   284|    const now = Date.now();
   285|    if (now - lastTapRef.current < 320) {
   286|      lastTapRef.current = 0;
   287|      setShowHeart(true);
   288|      setTimeout(() => setShowHeart(false), 800);
   289|      handleDoubleTapLike();
   290|    } else {
   291|      lastTapRef.current = now;
   292|      setTimeout(() => {
   293|        if (lastTapRef.current === now) {
   294|          setPaused((p) => !p);
   295|        }
   296|      }, 330);
   297|    }
   298|  }, []);
   299|
   300|  const handleDoubleTapLike = useCallback(() => {
   301|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
   302|    if (!liked) {
   303|      setLiked(true);
   304|      setLikeCount((prev) => prev + 1);
   305|    }
   306|    onLike(data);
   307|  }, [liked, onLike, data]);
   308|
   309|  const handleLikePress = useCallback(() => {
   310|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
   311|    const nextLiked = !liked;
   312|    setLiked(nextLiked);
   313|    setLikeCount((prev) => prev + (nextLiked ? 1 : -1));
   314|    onLike(data);
   315|  }, [liked, onLike, data]);
   316|
   317|  const handleSavePress = useCallback(() => {
   318|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
   319|    const nextSaved = !saved;
   320|    setSaved(nextSaved);
   321|    setSaveCount((prev) => prev + (nextSaved ? 1 : -1));
   322|    onSave(data);
   323|  }, [saved, onSave, data]);
   324|
   325|  const handleSharePress = useCallback(() => {
   326|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
   327|    onShare(data);
   328|  }, [onShare, data]);
   329|
   330|  const handleCommentPress = useCallback(() => {
   331|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
   332|    onComment(data);
   333|  }, [onComment, data]);
   334|
   335|  const handleViewDeal = useCallback(() => {
   336|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
   337|    onOpenDeal(data);
   338|  }, [onOpenDeal, data]);
   339|
   340|  const handleInvestNow = useCallback(() => {
   341|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Heavy);
   342|    onInvest(data);
   343|  }, [onInvest, data]);
   344|
   345|  // Rail position: account for safe area in reel mode, fixed offset in feed mode
   346|  const railBottom = isReel ? insets.bottom + 96 : 96;
   347|  const infoBottom = isReel ? insets.bottom + 26 : 26;
   348|
   349|  const renderMedia = () => {
   350|    if (data.mediaType === 'video' && data.mediaUrl) {
   351|      if (isReel) {
   352|        // Reel mode: use ReelVideoPlayer with mount/unmount lifecycle
   353|        if (shouldMountVideo) {
   354|          return (
   355|            <ReelVideoPlayer
   356|              videoId={data.reelId}
   357|              uri={data.mediaUrl}
   358|              hlsUri={data.hlsUrl}
   359|              posterUri={data.posterUrl}
   360|              previewBlurUri={data.previewBlurUrl}
   361|              shouldPlay={shouldPlay}
   362|              isMuted={isMuted}
   363|              onProgress={(p) => setProgress(p)}
   364|              testID={`${testIDPrefix}-player-${data.reelId}`}
   365|            />
   366|          );
   367|        }
   368|        // Unmounted: show poster to preserve scroll position
   369|        return (
   370|          <View style={StyleSheet.absoluteFill}>
   371|            {data.posterUrl ? (
   372|              <Image
   373|                source={{ uri: data.posterUrl }}
   374|                style={StyleSheet.absoluteFill}
   375|                contentFit="cover"
   376|                transition={150}
   377|              />
   378|            ) : data.previewBlurUrl ? (
   379|              <Image
   380|                source={{ uri: data.previewBlurUrl }}
   381|                style={StyleSheet.absoluteFill}
   382|                contentFit="cover"
   383|                blurRadius={20}
   384|                transition={100}
   385|              />
   386|            ) : (
   387|              <View style={[StyleSheet.absoluteFill, { backgroundColor: '#111' }]} />
   388|            )}
   389|          </View>
   390|        );
   391|      }
   392|      // Feed mode: use SafeVideo with viewability-based playback
   393|      return (
   394|        <SafeVideo
   395|          uri={data.mediaUrl}
   396|          posterUri={data.posterUrl ?? undefined}
   397|          style={StyleSheet.absoluteFill}
   398|          resizeMode={ResizeMode.COVER}
   399|          shouldPlay={shouldPlay}
   400|          isMuted={isMuted}
   401|          isLooping
   402|          testID={`${testIDPrefix}-video-${data.reelId}`}
   403|        />
   404|      );
   405|    }
   406|    // Image media
   407|    if (data.mediaUrl) {
   408|      return (
   409|        <Image
   410|          source={{ uri: data.mediaUrl }}
   411|          style={StyleSheet.absoluteFill}
   412|          contentFit="cover"
   413|          transition={200}
   414|        />
   415|      );
   416|    }
   417|    // Fallback: dark background
   418|    return <View style={[StyleSheet.absoluteFill, { backgroundColor: '#111' }]} />;
   419|  };
   420|
   421|  return (
   422|    <View
   423|      ref={viewRef}
   424|      style={[styles.container, { height: cardHeight }]}
   425|      testID={`${testIDPrefix}-${data.reelId}`}
   426|    >
   427|      {/* Full-bleed media */}
   428|      <TouchableOpacity
   429|        style={StyleSheet.absoluteFill}
   430|        activeOpacity={1}
   431|        onPress={handleTap}
   432|        testID={`${testIDPrefix}-touch-${data.reelId}`}
   433|      >
   434|        {renderMedia()}
   435|      </TouchableOpacity>
   436|
   437|      {/* Progress bar (video only) */}
   438|      {data.mediaType === 'video' && (
   439|        <View style={styles.progressBar}>
   440|          <View style={[styles.progressFill, { width: `${progress * 100}%` }]} />
   441|        </View>
   442|      )}
   443|
   444|      {/* Center play button when paused (video only) */}
   445|      {!shouldPlay && data.mediaType === 'video' && (
   446|        <View pointerEvents="none" style={styles.centerPlay}>
   447|          <View style={styles.centerPlayCircle}>
   448|            <Play size={30} color="#000" fill="#000" />
   449|          </View>
   450|        </View>
   451|      )}
   452|
   453|      {/* Double-tap heart burst */}
   454|      {showHeart && (
   455|        <View pointerEvents="none" style={styles.burstHeart}>
   456|          <Heart size={96} color={Colors.error} fill={Colors.error} />
   457|        </View>
   458|      )}
   459|
   460|      {/* Right action rail — Instagram-style outline icons with counts */}
   461|      <View style={[styles.rail, { bottom: railBottom }]}>
   462|        <TouchableOpacity
   463|          style={styles.railBtn}
   464|          onPress={handleLikePress}
   465|          testID={`${testIDPrefix}-like-${data.reelId}`}
   466|          activeOpacity={0.8}
   467|        >
   468|          <View style={styles.railIconCircle}>
   469|            <Heart
   470|              size={isReel ? 28 : 24}
   471|              color={liked ? Colors.error : '#fff'}
   472|              strokeWidth={1.5}
   473|            />
   474|          </View>
   475|          <Text style={styles.railCount}>{formatCount(likeCount)}</Text>
   476|        </TouchableOpacity>
   477|
   478|        <TouchableOpacity
   479|          style={styles.railBtn}
   480|          onPress={handleCommentPress}
   481|          testID={`${testIDPrefix}-comment-${data.reelId}`}
   482|          activeOpacity={0.8}
   483|        >
   484|          <View style={styles.railIconCircle}>
   485|            <MessageCircle size={isReel ? 28 : 24} color="#fff" strokeWidth={1.5} />
   486|          </View>
   487|          <Text style={styles.railCount}>{formatCount(data.commentCount)}</Text>
   488|        </TouchableOpacity>
   489|
   490|        <TouchableOpacity
   491|          style={styles.railBtn}
   492|          onPress={handleSavePress}
   493|          testID={`${testIDPrefix}-save-${data.reelId}`}
   494|          activeOpacity={0.8}
   495|        >
   496|          <View style={styles.railIconCircle}>
   497|            <Bookmark
   498|              size={isReel ? 28 : 24}
   499|              color={saved ? Colors.primary : '#fff'}
   500|              strokeWidth={1.5}
   501|            />
   502|          </View>
   503|          <Text style={styles.railCount}>{formatCount(saveCount)}</Text>
   504|        </TouchableOpacity>
   505|
   506|        <TouchableOpacity
   507|          style={styles.railBtn}
   508|          onPress={handleSharePress}
   509|          testID={`${testIDPrefix}-share-${data.reelId}`}
   510|          activeOpacity={0.8}
   511|        >
   512|          <View style={styles.railIconCircle}>
   513|            <Share2 size={isReel ? 28 : 24} color="#fff" strokeWidth={1.5} />
   514|          </View>
   515|          <Text style={styles.railCount}>{formatCount(data.shareCount)}</Text>
   516|        </TouchableOpacity>
   517|
   518|        {data.mediaType === 'video' && (
   519|          <TouchableOpacity
   520|            style={styles.railBtn}
   521|            onPress={onToggleMute}
   522|            testID={`${testIDPrefix}-mute-${data.reelId}`}
   523|            activeOpacity={0.8}
   524|          >
   525|            <View style={styles.railIconCircle}>
   526|              {isMuted ? <VolumeX size={24} color="#fff" strokeWidth={1.5} /> : <Volume2 size={24} color="#fff" strokeWidth={1.5} />}
   527|            </View>
   528|          </TouchableOpacity>
   529|        )}
   530|      </View>
   531|
   532|      {/* Bottom info + CTAs */}
   533|      <View pointerEvents="box-none" style={[styles.info, { bottom: infoBottom }]}>
   534|        <LinearGradient
   535|          colors={['transparent', 'rgba(0,0,0,0.55)', 'rgba(0,0,0,0.82)']}
   536|          locations={[0, 0.35, 1]}
   537|          style={styles.bottomGradient}
   538|        />
   539|
   540|        {/* Badges */}
   541|        <View style={styles.badgeRow}>
   542|          {hasDeal && <Text style={styles.badgeInvestment}>INVESTMENT</Text>}
   543|          {isActiveStatus && <Text style={styles.badgeActive}>ACTIVE</Text>}
   544|        </View>
   545|
   546|        {/* Title */}
   547|        <Text style={styles.infoTitle} numberOfLines={1}>
   548|          {data.title}
   549|        </Text>
   550|        {data.subtitle ? (
   551|          <Text style={styles.infoSubtitle} numberOfLines={1}>
   552|            {data.subtitle}
   553|          </Text>
   554|        ) : null}
   555|        {data.location ? (
   556|          <Text style={styles.infoLocation} numberOfLines={1}>
   557|            {data.location}
   558|          </Text>
   559|        ) : null}
   560|
   561|        {/* Metrics */}
   562|        <View style={styles.metricRow}>
   563|          {data.roi != null && data.roi > 0 ? (
   564|            <View style={styles.metric}>
   565|              <Text style={styles.metricValue}>{data.roi}%</Text>
   566|              <Text style={styles.metricLabel}>ROI</Text>
   567|            </View>
   568|          ) : null}
   569|          {data.minimumInvestment != null && data.minimumInvestment > 0 ? (
   570|            <View style={styles.metric}>
   571|              <Text style={styles.metricValue}>{compactCurrency(data.minimumInvestment)}</Text>
   572|              <Text style={styles.metricLabel}>MIN INVEST</Text>
   573|            </View>
   574|          ) : null}
   575|          {data.minimumOwnership ? (
   576|            <View style={styles.metric}>
   577|              <Text style={styles.metricValue}>{data.minimumOwnership}</Text>
   578|              <Text style={styles.metricLabel}>MIN OWNERSHIP</Text>
   579|            </View>
   580|          ) : null}
   581|        </View>
   582|
   583|        {/* Investment category options */}
