     1|/**
     2| * Owner-only APK/AAB distribution presign endpoint.
     3| *
     4| * Mints a short-lived (15 min) presigned S3 PUT URL restricted to the
     5| * `apk/` prefix of the public download bucket so a build agent can upload
     6| * a release artifact WITHOUT AWS credentials ever leaving the runtime.
     7| *
     8| * Guards:
     9| *  - Registered owner bearer required (assertIVXRegisteredOwnerBearer)
    10| *  - Explicit confirmation phrase CONFIRM_IVX_APK_UPLOAD (409 without it)
    11| *  - Key restricted to apk/<safe-name>.(apk|aab)
    12| *  - Secrets are never returned; only the signed URL is.
    13| */
    14|import { createHash, createHmac } from 'node:crypto';
    15|
    16|import { getRawOwnerVariableValue } from './ivx-owner-variables';
    17|import { IVXOwnerApprovalError, assertIVXRegisteredOwnerBearer, ownerOnlyJson, ownerOnlyOptions } from './owner-only';
    18|
    19|const IVX_APK_UPLOAD_CONFIRM_PHRASE = 'CONFIRM_IVX_APK_UPLOAD';
    20|const IVX_APK_KEY_PATTERN = /^apk\/[A-Za-z0-9][A-Za-z0-9._-]{0,120}\.(apk|aab)$/;
    21|const IVX_APK_PRESIGN_EXPIRES_SECONDS = 900;
    22|const IVX_APK_BUCKET_DEFAULT = 'ivxholding.com';
    23|
    24|export function OPTIONS(): Response {
    25|  return ownerOnlyOptions();
    26|}
    27|
    28|function readEnv(name: string): string {
    29|  return (process.env[name] ?? '').trim();
    30|}
    31|
    32|type PresignInput = {
    33|  bucket: string;
    34|  region: string;
    35|  key: string;
    36|  accessKeyId: string;
    37|  secretAccessKey: string;
    38|  expiresSeconds: number;
    39|  now: Date;
    40|};
    41|
    42|function hmac(key: Buffer | string, value: string): Buffer {
    43|  return createHmac('sha256', key).update(value).digest();
    44|}
    45|
    46|function sha256Hex(value: string): string {
    47|  return createHash('sha256').update(value).digest('hex');
    48|}
    49|
    50|/**
    51| * Build a SigV4 query-string presigned PUT URL (UNSIGNED-PAYLOAD, host-only
    52| * signed header). Pure and deterministic for a fixed `now` so it is unit-testable.
    53| *
    54| * Uses PATH-STYLE addressing (s3.<region>.amazonaws.com/<bucket>/<key>) because
    55| * bucket names containing dots (e.g. `ivxholding.com`) break TLS on the
    56| * virtual-hosted wildcard certificate (*.s3.<region>.amazonaws.com).
    57| */
    58|export function buildIVXS3PresignedPutUrl(input: PresignInput): string {
    59|  const amzDate = input.now.toISOString().replace(/[:.-]/g, '').slice(0, 15) + 'Z';
    60|  const dateStamp = amzDate.slice(0, 8);
    61|  const host = `s3.${input.region}.amazonaws.com`;
    62|  const credentialScope = `${dateStamp}/${input.region}/s3/aws4_request`;
    63|
    64|  const queryEntries: [string, string][] = [
    65|    ['X-Amz-Algorithm', 'AWS4-HMAC-SHA256'],
    66|    ['X-Amz-Credential', `${input.accessKeyId}/${credentialScope}`],
    67|    ['X-Amz-Date', amzDate],
    68|    ['X-Amz-Expires', String(input.expiresSeconds)],
    69|    ['X-Amz-SignedHeaders', 'host'],
    70|  ];
    71|  const canonicalQuery = queryEntries
    72|    .map(([name, value]) => `${encodeURIComponent(name)}=${encodeURIComponent(value)}`)
    73|    .sort()
    74|    .join('&');
    75|
    76|  const canonicalRequest = [
    77|    'PUT',
    78|    `/${input.bucket}/${input.key}`,
    79|    canonicalQuery,
    80|    `host:${host}\n`,
    81|    'host',
    82|    'UNSIGNED-PAYLOAD',
    83|  ].join('\n');
    84|
    85|  const stringToSign = [
    86|    'AWS4-HMAC-SHA256',
    87|    amzDate,
    88|    credentialScope,
    89|    sha256Hex(canonicalRequest),
    90|  ].join('\n');
    91|
